<?php get_header(); while (have_posts()) : the_post(); ?>
<main id="main" class="shell page-main <?php echo is_page('saved') ? 'saved-main' : ''; ?>"><div class="page-heading"><p class="eyebrow"><?php echo is_page('saved') ? 'THE ONES YOU WANT TO COME BACK TO' : 'THE AFTERGLOW NOTEBOOK'; ?></p><h1><?php the_title(); ?></h1></div>
<?php if (is_page('saved')) : ?><p class="page-intro">A little collection of your own. Saved on this browser, just for you.</p><div id="saved-items" class="artist-grid directory-grid" aria-live="polite"></div><div id="saved-empty" class="empty-state"><?php echo ag_icon('heart'); ?><h2>Leave a little room for discovery.</h2><p>Tap the heart on an artist or song to keep it here. No account needed.</p><a class="button button-dark" href="<?php echo esc_url(ag_url('artists')); ?>">Find something to love <?php echo ag_icon('arrow'); ?></a></div><noscript><p>Your saved collection needs JavaScript. You can still browse every artist and song.</p></noscript>
<?php else : ?><div class="prose page-prose"><?php the_content(); ?><?php if (is_page(['contact', 'copyright'])) : $email = get_theme_mod('ag_contact_email', ''); if ($email) : ?><p><a class="button button-dark" href="<?php echo esc_url('mailto:' . sanitize_email($email)); ?>">Email <?php bloginfo('name'); ?> <?php echo ag_icon('arrow'); ?></a></p><?php else : ?><aside class="editorial-notice">Contact details will be available at launch. The site owner must set a public email under Appearance → Customize → Afterglow identity before publishing.</aside><?php endif; endif; ?></div><?php endif; ?></main>
<?php endwhile; get_footer(); ?>
